package example.hexagonal.adapter;

import example.hexagonal.application.OrderStore.DuplicateOrder;
import example.hexagonal.application.OrderStore.StorageFailure;
import example.hexagonal.application.Orders;
import example.hexagonal.domain.Order;
import java.security.Principal;
import java.util.UUID;
import org.springframework.http.HttpStatus;
import org.springframework.http.ProblemDetail;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
public final class HttpOrders {
    private final Orders orders;

    public HttpOrders(Orders orders) {
        this.orders = orders;
    }

    @PostMapping("/orders")
    public ResponseEntity<Created> create(Principal principal, @RequestBody Request request) {
        if (principal == null) {
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);
        }
        Order order = orders.create(new Orders.Actor(principal.getName()),
                new Orders.Create(request.id(), request.customerId(), request.quantity()));
        return ResponseEntity.status(HttpStatus.CREATED).body(new Created(order.id(), order.quantity()));
    }

    @ExceptionHandler(Orders.Forbidden.class)
    public ProblemDetail forbidden() {
        return ProblemDetail.forStatusAndDetail(HttpStatus.FORBIDDEN, "Customer access denied");
    }

    @ExceptionHandler(Order.InvalidOrder.class)
    public ProblemDetail invalid() {
        return ProblemDetail.forStatusAndDetail(HttpStatus.BAD_REQUEST, "Invalid order");
    }

    @ExceptionHandler(DuplicateOrder.class)
    public ProblemDetail duplicate() {
        return ProblemDetail.forStatusAndDetail(HttpStatus.CONFLICT, "Order ID already exists");
    }

    @ExceptionHandler(StorageFailure.class)
    public ProblemDetail storageFailure() {
        return ProblemDetail.forStatusAndDetail(HttpStatus.INTERNAL_SERVER_ERROR, "Order storage failed");
    }

    public record Request(UUID id, String customerId, int quantity) {}

    public record Created(UUID id, int quantity) {}
}

package example.hexagonal.adapter;

import example.hexagonal.application.OrderStore;
import example.hexagonal.domain.Order;
import java.util.Optional;
import java.util.UUID;
import org.springframework.dao.DataAccessException;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;

public final class JdbcOrders implements OrderStore {
    private final JdbcTemplate jdbc;

    public JdbcOrders(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public void insert(Order order) {
        try {
            jdbc.update("insert into orders (id, customer_id, quantity) values (?, ?, ?)",
                    order.id().toString(), order.customerId(), order.quantity());
        } catch (DuplicateKeyException failure) {
            // The fixture schema has only one unique key: the order ID.
            throw new DuplicateOrder(order.id(), failure);
        } catch (DataAccessException failure) {
            throw new StorageFailure(failure);
        }
    }

    @Override
    public void auditCreation(UUID id) {
        try {
            jdbc.update("insert into order_audit (order_id, action) values (?, ?)",
                    id.toString(), "CREATE");
        } catch (DataAccessException failure) {
            // An audit constraint failure is not an order-ID conflict.
            throw new StorageFailure(failure);
        }
    }

    @Override
    public Optional<Order> find(UUID id) {
        try {
            return jdbc.query("select id, customer_id, quantity from orders where id = ?",
                    (row, number) -> new Order(UUID.fromString(row.getString("id")),
                            row.getString("customer_id"), row.getInt("quantity")),
                    id.toString()).stream().findFirst();
        } catch (DataAccessException failure) {
            throw new StorageFailure(failure);
        }
    }
}

package example.hexagonal.application;

import example.hexagonal.domain.Order;
import java.util.Objects;

public final class CreateOrder implements Orders {
    private final OrderStore store;

    public CreateOrder(OrderStore store) {
        this.store = Objects.requireNonNull(store);
    }

    @Override
    public Order create(Actor actor, Create command) {
        Objects.requireNonNull(command);
        if (actor == null || !actor.customerId().equals(command.customerId())) {
            throw new Forbidden();
        }
        Order order = new Order(command.id(), command.customerId(), command.quantity());
        store.insert(order);
        store.auditCreation(order.id());
        return order;
    }
}

package example.hexagonal.application;

import example.hexagonal.domain.Order;
import java.util.UUID;

/** Input port. Actor identity comes from a trusted adapter, never the request body. */
public interface Orders {
    Order create(Actor actor, Create command);

    record Actor(String customerId) {
        public Actor {
            if (customerId == null || customerId.isBlank()) {
                throw new IllegalArgumentException("A trusted customer identity is required");
            }
        }
    }

    record Create(UUID id, String customerId, int quantity) {}

    final class Forbidden extends RuntimeException {
        public Forbidden() {
            super("The actor cannot create orders for this customer");
        }
    }
}

package example.hexagonal.application;

import example.hexagonal.domain.Order;
import java.util.Optional;
import java.util.UUID;

/**
 * Output port. Writes join the caller's local transaction; they do not commit it.
 * The ID is globally unique. A duplicate is a conflict, not an idempotent replay.
 * find is an internal storage operation; it is not an authorized public query.
 */
public interface OrderStore {
    void insert(Order order);

    void auditCreation(UUID id);

    Optional<Order> find(UUID id);

    final class DuplicateOrder extends RuntimeException {
        public DuplicateOrder(UUID id, Throwable cause) {
            super("Order already exists: " + id, cause);
        }
    }

    final class StorageFailure extends RuntimeException {
        public StorageFailure(Throwable cause) {
            super("Order storage failed", cause);
        }
    }
}

package example.hexagonal.domain;

import java.util.UUID;

public record Order(UUID id, String customerId, int quantity) {
    public Order {
        if (id == null || customerId == null || customerId.isBlank() || customerId.length() > 64) {
            throw new InvalidOrder("An ID and a customer of 1..64 characters are required");
        }
        if (quantity < 1 || quantity > 10) {
            throw new InvalidOrder("Quantity must be between 1 and 10");
        }
    }

    public static final class InvalidOrder extends RuntimeException {
        public InvalidOrder(String message) {
            super(message);
        }
    }
}

