package example.persistence;

import org.springframework.boot.autoconfigure.SpringBootApplication;

@SpringBootApplication(proxyBeanMethods = false)
public class FixtureApplication {}

package example.persistence;

import jakarta.persistence.CascadeType;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.OneToMany;
import jakarta.persistence.Version;
import java.util.ArrayList;
import java.util.List;

@Entity
public class Inventory {
    @Id
    @Column(length = 40, updatable = false)
    private String sku;

    @Version
    @Column(nullable = false)
    private Long version;

    @Column(nullable = false, length = 200)
    private String description;

    @Column(nullable = false)
    private int available;

    @Column(length = 500)
    private String note;

    @OneToMany(mappedBy = "inventory", cascade = CascadeType.ALL, orphanRemoval = true)
    private List<Movement> movements = new ArrayList<>();

    protected Inventory() {}

    public Inventory(String sku, String description, int available) {
        if (sku == null || sku.isBlank() || sku.length() > 40 || description == null
                || description.length() > 200 || available < 0) {
            throw new IllegalArgumentException("SKU, description and nonnegative stock are required");
        }
        this.sku = sku;
        this.description = description;
        this.available = available;
    }

    public void reserve(int quantity) {
        if (quantity <= 0 || quantity > available) {
            throw new IllegalArgumentException("Reservation must be positive and fit available stock");
        }
        available -= quantity;
        movements.add(new Movement(this, quantity));
    }

    public void changeNote(String note) {
        if (note != null && note.length() > 500) {
            throw new IllegalArgumentException("Note must fit 500 UTF-16 code units in this fixture");
        }
        this.note = note;
    }

    public String getSku() { return sku; }
    public Long getVersion() { return version; }
    public String getDescription() { return description; }
    public int getAvailable() { return available; }
    public String getNote() { return note; }
    public List<Movement> getMovements() { return List.copyOf(movements); }
}

package example.persistence;

public abstract sealed class InventoryException extends RuntimeException
        permits InventoryNotFoundException, InventoryVersionConflictException {
    private final String code;

    protected InventoryException(String code, String message) {
        super(message);
        this.code = code;
    }

    public final String code() { return code; }
}

package example.persistence;

import java.util.Objects;

public final class InventoryNotFoundException extends InventoryException {
    private final String sku;

    public InventoryNotFoundException(String sku) {
        super("INVENTORY_NOT_FOUND", "Inventory with SKU " + Objects.requireNonNull(sku) + " was not found.");
        this.sku = sku;
    }

    public String sku() { return sku; }
}

package example.persistence;

import java.util.Optional;
import org.springframework.data.jpa.repository.EntityGraph;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.transaction.annotation.Transactional;

public interface InventoryRepository extends JpaRepository<Inventory, String> {
    @EntityGraph(attributePaths = "movements")
    @Transactional(readOnly = true)
    Optional<Inventory> findWithMovementsBySku(String sku);
}

package example.persistence;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class InventoryService {
    private final InventoryRepository inventory;

    public InventoryService(InventoryRepository inventory) {
        this.inventory = inventory;
    }

    @Transactional
    public void reserve(String sku, int quantity) {
        // The managed entity keeps omitted fields; @Version rejects stale competing updates.
        findRequiredBySku(sku).reserve(quantity);
    }

    @Transactional
    public void changeNote(String sku, Long expectedVersion, String note) {
        if (expectedVersion == null) {
            throw new IllegalArgumentException("The client's expected version is required");
        }
        Inventory item = findRequiredBySku(sku);
        if (!expectedVersion.equals(item.getVersion())) {
            throw new InventoryVersionConflictException(sku, expectedVersion, item.getVersion());
        }
        // Never assign expectedVersion to @Version. Hibernate still detects a race at commit.
        item.changeNote(note);
    }

    private Inventory findRequiredBySku(String sku) {
        return inventory.findById(sku).orElseThrow(() -> new InventoryNotFoundException(sku));
    }
}

package example.persistence;

import java.util.Objects;

public final class InventoryVersionConflictException extends InventoryException {
    private final String sku;
    private final long expectedVersion;
    private final long currentVersion;

    public InventoryVersionConflictException(String sku, long expectedVersion, long currentVersion) {
        super("INVENTORY_VERSION_CONFLICT", "Inventory with SKU " + Objects.requireNonNull(sku)
                + " has version " + currentVersion + "; expected " + expectedVersion + ".");
        this.sku = sku;
        this.expectedVersion = expectedVersion;
        this.currentVersion = currentVersion;
    }

    public String sku() { return sku; }
    public long expectedVersion() { return expectedVersion; }
    public long currentVersion() { return currentVersion; }
}

package example.persistence;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.FetchType;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.ManyToOne;

@Entity
public class Movement {
    @Id
    @GeneratedValue(strategy = GenerationType.SEQUENCE)
    private Long id;

    @ManyToOne(fetch = FetchType.LAZY, optional = false)
    @JoinColumn(name = "inventory_sku", nullable = false, updatable = false)
    private Inventory inventory;

    @Column(nullable = false, updatable = false)
    private int quantity;

    protected Movement() {}

    Movement(Inventory inventory, int quantity) {
        if (inventory == null || quantity <= 0) {
            throw new IllegalArgumentException("Movement requires an owner and positive quantity");
        }
        this.inventory = inventory;
        this.quantity = quantity;
    }

    public Long getId() { return id; }
    public int getQuantity() { return quantity; }
}

package example.persistence;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import jakarta.persistence.EntityManager;
import jakarta.persistence.EntityManagerFactory;
import jakarta.persistence.OptimisticLockException;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.test.context.TestConstructor;
import org.springframework.transaction.support.TransactionTemplate;

@SpringBootTest(properties = {
        "spring.datasource.url=jdbc:h2:mem:inventory-service;DB_CLOSE_DELAY=-1",
        "spring.jpa.hibernate.ddl-auto=create-drop"
})
@TestConstructor(autowireMode = TestConstructor.AutowireMode.ALL)
class InventoryServiceTest {
    private final InventoryRepository inventory;
    private final InventoryService service;
    private final TransactionTemplate transactions;
    private final EntityManagerFactory entityManagers;

    InventoryServiceTest(InventoryRepository inventory, InventoryService service,
                         TransactionTemplate transactions, EntityManagerFactory entityManagers) {
        this.inventory = inventory;
        this.service = service;
        this.transactions = transactions;
        this.entityManagers = entityManagers;
    }

    @BeforeEach
    void seedCommittedState() {
        inventory.deleteAll();
        inventory.saveAndFlush(new Inventory("A", "Retain this description", 20));
    }

    @Test
    void reservationCommitsStockAndMovementWithoutReplacingOtherFields() {
        service.reserve("A", 3);

        Inventory result = inventory.findWithMovementsBySku("A").orElseThrow();
        assertEquals(17, result.getAvailable());
        assertEquals("Retain this description", result.getDescription());
        assertEquals(1, result.getMovements().size());
        assertEquals(3, result.getMovements().getFirst().getQuantity());
        assertNotNull(result.getMovements().getFirst().getId());
    }

    @Test
    void failureAfterFlushRollsBackStockAndMovement() {
        assertThrows(IllegalStateException.class, () -> transactions.executeWithoutResult(status -> {
            service.reserve("A", 3);
            inventory.flush();
            throw new IllegalStateException("Fail after SQL execution");
        }));

        Inventory result = inventory.findWithMovementsBySku("A").orElseThrow();
        assertEquals(20, result.getAvailable());
        assertTrue(result.getMovements().isEmpty());
    }

    @Test
    void duplicateKeyAtCommitRollsBackCompanionInsert() {
        AtomicBoolean callbackCompleted = new AtomicBoolean();
        assertThrows(DataIntegrityViolationException.class,
                () -> transactions.executeWithoutResult(status -> {
                    inventory.save(new Inventory("B", "Companion insert", 10));
                    inventory.save(new Inventory("A", "Duplicate key", 5));
                    callbackCompleted.set(true);
                }));

        // Both saves returned; failure happened when the owning transaction completed.
        assertTrue(callbackCompleted.get());
        assertTrue(inventory.findById("B").isEmpty());
        Inventory original = inventory.findById("A").orElseThrow();
        assertEquals("Retain this description", original.getDescription());
        assertEquals(20, original.getAvailable());
        assertEquals(1, inventory.count());
    }

    @Test
    void staleClientVersionIsRejectedEvenWhenTheServiceLoadsCurrentState() {
        Long clientVersion = inventory.findById("A").orElseThrow().getVersion();
        service.changeNote("A", clientVersion, "Committed by another client");
        Long currentVersion = inventory.findById("A").orElseThrow().getVersion();
        assertNotEquals(clientVersion, currentVersion);

        InventoryVersionConflictException conflict = assertThrows(InventoryVersionConflictException.class,
                () -> service.changeNote("A", clientVersion, "Stale overwrite"));
        assertEquals("INVENTORY_VERSION_CONFLICT", conflict.code());
        assertEquals("A", conflict.sku());
        assertEquals(clientVersion.longValue(), conflict.expectedVersion());
        assertEquals(currentVersion.longValue(), conflict.currentVersion());

        Inventory result = inventory.findById("A").orElseThrow();
        assertEquals("Committed by another client", result.getNote());
        assertEquals(currentVersion, result.getVersion());
        assertEquals("Retain this description", result.getDescription());
    }

    @Test
    void currentVersionAllowsAnEditAndThenClearingTheNote() {
        Long clientVersion = inventory.findById("A").orElseThrow().getVersion();
        service.changeNote("A", clientVersion, "Current edit");

        Inventory edited = inventory.findById("A").orElseThrow();
        assertEquals("Current edit", edited.getNote());
        assertNotEquals(clientVersion, edited.getVersion());
        service.changeNote("A", edited.getVersion(), null);

        Inventory cleared = inventory.findById("A").orElseThrow();
        assertNull(cleared.getNote());
        assertNotEquals(edited.getVersion(), cleared.getVersion());
        assertEquals("Retain this description", cleared.getDescription());
        assertEquals(20, cleared.getAvailable());
    }

    @Test
    void missingVersionCannotBypassTheConditionalEdit() {
        Long version = inventory.findById("A").orElseThrow().getVersion();
        assertThrows(IllegalArgumentException.class, () -> service.changeNote("A", null, "Unchecked"));
        Inventory result = inventory.findById("A").orElseThrow();
        assertNull(result.getNote());
        assertEquals(version, result.getVersion());
    }

    @Test
    void missingInventoryIdentifiesTheRequestedSkuWithoutChangingStoredState() {
        InventoryNotFoundException reservation = assertThrows(InventoryNotFoundException.class,
                () -> service.reserve("MISSING-RESERVATION", 3));
        assertEquals("INVENTORY_NOT_FOUND", reservation.code());
        assertEquals("MISSING-RESERVATION", reservation.sku());
        assertTrue(reservation.getMessage().contains(reservation.sku()));

        InventoryNotFoundException edit = assertThrows(InventoryNotFoundException.class,
                () -> service.changeNote("MISSING-EDIT", 0L, "Unstored"));
        assertEquals("MISSING-EDIT", edit.sku());
        assertTrue(edit.getMessage().contains(edit.sku()));

        Inventory result = inventory.findWithMovementsBySku("A").orElseThrow();
        assertEquals(20, result.getAvailable());
        assertNull(result.getNote());
        assertTrue(result.getMovements().isEmpty());
        assertEquals(1, inventory.count());
    }

    @Test
    void competingTransactionsCannotBothReserveFromTheSameVersion() {
        // Two open persistence contexts model overlapping reads without timing sleeps.
        try (EntityManager first = entityManagers.createEntityManager();
             EntityManager second = entityManagers.createEntityManager()) {
            first.getTransaction().begin();
            second.getTransaction().begin();
            try {
                Inventory firstRead = first.find(Inventory.class, "A");
                Inventory secondRead = second.find(Inventory.class, "A");
                firstRead.reserve(3);
                secondRead.reserve(4);
                first.getTransaction().commit();
                assertThrows(OptimisticLockException.class, second::flush);
            } finally {
                if (first.getTransaction().isActive()) first.getTransaction().rollback();
                if (second.getTransaction().isActive()) second.getTransaction().rollback();
            }
        }
        Inventory result = inventory.findWithMovementsBySku("A").orElseThrow();
        assertEquals(17, result.getAvailable());
        assertEquals(1, result.getMovements().size());
        assertEquals(3, result.getMovements().getFirst().getQuantity());
    }

    @Test
    void optionalNoteAcceptsItsLimitAndRejectsAnOversizedEdit() {
        Inventory initial = inventory.findById("A").orElseThrow();
        assertNull(initial.getNote());
        service.changeNote("A", initial.getVersion(), "n".repeat(500));
        Inventory saved = inventory.findById("A").orElseThrow();
        assertEquals(500, saved.getNote().length());

        assertThrows(IllegalArgumentException.class,
                () -> service.changeNote("A", saved.getVersion(), "n".repeat(501)));
        Inventory result = inventory.findById("A").orElseThrow();
        assertEquals(saved.getNote(), result.getNote());
        assertEquals(saved.getVersion(), result.getVersion());
    }
}

