package example.harness;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Ticket {
    @Id
    private String id;
    @Column(nullable = false, length = 40)
    private String note;

    protected Ticket() {}

    public Ticket(String id, String note) {
        this.id = id;
        this.note = note;
    }

    public String getId() { return id; }
    public String getNote() { return note; }
}

package example.harness;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.util.UriComponentsBuilder;

@RestController
public class TicketController {
    private final TicketService tickets;

    public TicketController(TicketService tickets) { this.tickets = tickets; }

    @PostMapping("/tickets")
    public ResponseEntity<Void> create(@Valid @RequestBody NewTicket ticket) {
        tickets.create(ticket.id(), ticket.note());
        var location = UriComponentsBuilder.fromPath("/tickets/{id}")
                .encode().buildAndExpand(ticket.id()).toUri();
        return ResponseEntity.created(location).build();
    }

    @GetMapping("/tickets/{id}")
    public ResponseEntity<String> read(@PathVariable String id) {
        return ResponseEntity.ok(tickets.read(id));
    }

    public record NewTicket(@NotBlank String id, @NotBlank @Size(max = 40) String note) {}
}

package example.harness;

import org.springframework.data.jpa.repository.JpaRepository;

public interface TicketRepository extends JpaRepository<Ticket, String> {}

package example.harness;

import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class TicketService {
    private final TicketRepository tickets;

    public TicketService(TicketRepository tickets) {
        this.tickets = tickets;
    }

    @Transactional
    public void create(String id, String note) {
        tickets.save(new Ticket(id, note));
    }

    @Transactional(readOnly = true)
    public String read(String id) {
        return tickets.findById(id)
                .orElseThrow(() -> new MissingTicket(id))
                .getNote();
    }

    public static class MissingTicket extends RuntimeException {
        public MissingTicket(String id) { super(id); }
    }
}

package example.harness;

import static org.mockito.BDDMockito.given;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.user;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.webmvc.test.autoconfigure.WebMvcTest;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(TicketController.class)
@Import({ApiErrors.class, ApiSecurity.class})
class MvcSliceTest {
    private static final String VALID_TICKET = """
            {"id":"a","note":"valid"}
            """;

    @Autowired
    MockMvc mvc;

    @MockitoBean
    TicketService tickets;

    @Test
    void realChainRejectsAnonymousAndInsufficientAuthorityBeforeTheService() throws Exception {
        mvc.perform(get("/tickets/missing")).andExpect(status().isUnauthorized());
        mvc.perform(post("/tickets").with(user("reader").roles("READER")).with(csrf())
                        .contentType("application/json").content(VALID_TICKET))
                .andExpect(status().isForbidden());
        verifyNoInteractions(tickets);
    }

    @Test
    void realChainKeepsCsrfAndAllowsAnAuthorizedRequest() throws Exception {
        mvc.perform(post("/tickets").with(user("writer").roles("WRITER"))
                        .contentType("application/json").content(VALID_TICKET))
                .andExpect(status().isForbidden());
        verifyNoInteractions(tickets);
        mvc.perform(post("/tickets").with(user("writer").roles("WRITER")).with(csrf())
                        .contentType("application/json").content(VALID_TICKET))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "/tickets/a"));
        verify(tickets).create("a", "valid");
    }

    @Test
    void realAdviceHandlesBindingValidationAndTheServiceFailure() throws Exception {
        mvc.perform(post("/tickets").with(user("writer").roles("WRITER")).with(csrf())
                        .contentType("application/json").content("""
                                {"id":"a","note":""}
                                """))
                .andExpect(status().isBadRequest()).andExpect(jsonPath("$.detail").value("Invalid ticket"));
        verifyNoInteractions(tickets);
        given(tickets.read("missing")).willThrow(new TicketService.MissingTicket("missing"));
        mvc.perform(get("/tickets/missing").with(user("reader")))
                .andExpect(status().isNotFound()).andExpect(jsonPath("$.detail").value("Ticket not found"));
    }

}

package example.harness;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import jakarta.persistence.PersistenceException;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
import org.springframework.boot.jpa.test.autoconfigure.TestEntityManager;
import org.springframework.test.context.transaction.AfterTransaction;

@DataJpaTest
class TicketRepositoryTest {
    @Autowired
    TicketRepository tickets;

    @Autowired
    TestEntityManager entities;

    private final String id = UUID.randomUUID().toString();

    @Test
    void noteRoundTripsThroughTheDatabase() {
        tickets.save(new Ticket(id, "printer unavailable"));
        entities.flush();
        entities.clear();

        assertThat(tickets.findById(id)).get()
                .extracting(Ticket::getNote).isEqualTo("printer unavailable");
    }

    @Test
    void flushExposesTheDatabaseLengthConstraint() {
        entities.persist(new Ticket(id, "x".repeat(41)));

        assertThatThrownBy(entities::flush).isInstanceOf(PersistenceException.class);
    }

    @AfterTransaction
    void testWritesWereRolledBack() {
        assertThat(tickets.existsById(id)).isFalse();
    }
}

package example.harness;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.UUID;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.transaction.TestTransaction;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@DataJpaTest
@Import(TicketService.class)
@Transactional(propagation = Propagation.NOT_SUPPORTED)
class TicketServiceCommitTest {
    @Autowired
    TicketService service;

    @Autowired
    TicketRepository tickets;

    private final String id = UUID.randomUUID().toString();

    @Test
    void createdTicketIsVisibleAfterTheServiceReturns() {
        assertThat(TestTransaction.isActive()).isFalse();
        service.create(id, "printer unavailable");

        assertThat(tickets.findById(id)).get()
                .extracting(Ticket::getNote).isEqualTo("printer unavailable");
    }

    @AfterEach
    void removeCommittedTestData() {
        tickets.deleteById(id);
        assertThat(tickets.existsById(id)).isFalse();
    }
}

